insert into public.academic_skill_framework_crosswalks(
 registry_version_id,node_id,provider_name,programme_code,programme_name,phase,
 external_strand,external_reference_code,alignment_level,alignment_note,source_url,source_version,status
)
select v.id,n.id,s.provider_name,s.programme_code,s.programme_name,s.phase,
 s.external_strand,s.external_reference_code,s.alignment_level,s.alignment_note,
 s.source_url,s.source_version,s.status
from seed s
join public.academic_skill_registry_versions v on v.code=s.version_code
join public.academic_skill_registry_nodes n on n.registry_version_id=v.id and n.code=s.node_code
on conflict do nothing;
